import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { UserFeedbackService } from 'src/app/services/user-feedback.service';
import { Feedback } from 'src/app/models/feedback.model';
import {
  trigger,
  transition,
  style,
  animate,
  query,
  stagger,
} from '@angular/animations';

@Component({
  selector: 'app-user-feedback',
  templateUrl: './user-feedback.component.html',
  styleUrls: ['./user-feedback.component.css'],
  animations: [
    trigger('fadeInUp', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateY(30px)' }),
        animate(
          '0.6s ease-out',
          style({ opacity: 1, transform: 'translateY(0)' }),
        ),
      ]),
    ]),
    trigger('slideInLeft', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateX(-30px)' }),
        animate(
          '0.5s ease-out',
          style({ opacity: 1, transform: 'translateX(0)' }),
        ),
      ]),
    ]),
    trigger('slideInOut', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateX(100%)' }),
        animate(
          '0.3s ease-out',
          style({ opacity: 1, transform: 'translateX(0)' }),
        ),
      ]),
      transition(':leave', [
        animate(
          '0.3s ease-in',
          style({ opacity: 0, transform: 'translateX(100%)' }),
        ),
      ]),
    ]),
    trigger('fadeInOut', [
      transition(':enter', [
        style({ opacity: 0 }),
        animate('0.3s ease-in', style({ opacity: 1 })),
      ]),
      transition(':leave', [animate('0.2s ease-out', style({ opacity: 0 }))]),
    ]),
    trigger('fadeIn', [
      transition(':enter', [
        style({ opacity: 0 }),
        animate('0.8s ease-in', style({ opacity: 1 })),
      ]),
    ]),
  ],
})
export class UserFeedbackComponent implements OnInit {
  successMessage: string = '';
  itemId: number = 0;
  isSubmitting = false;

  feedback: Feedback = {
    customerName: '',
    email: '',
    message: '',
  };

  constructor(
    private route: ActivatedRoute,
    private feedbackService: UserFeedbackService,
    private router: Router,
  ) {}

  ngOnInit(): void {
    this.route.queryParams.subscribe((params) => {
      this.successMessage = params['success'] || '';
      this.itemId = +params['itemId'] || 0;

      // Auto-fill from localStorage
      const storedName = localStorage.getItem('username');
      if (storedName) {
        this.feedback.customerName = storedName;
        // Try to get stored email or generate one
        const storedEmail = localStorage.getItem('email');
        if (storedEmail) {
          this.feedback.email = storedEmail;
        } else {
          this.feedback.email = storedName + '@example.com';
        }
      }
    });

    // Auto-hide success message after 5 seconds
    if (this.successMessage) {
      setTimeout(() => {
        this.successMessage = '';
      }, 5000);
    }
  }

  onSubmit() {
    if (this.isSubmitting) return;

    this.isSubmitting = true;

    this.feedbackService.submitFeedback(this.feedback).subscribe({
      next: (res) => {
        alert('Thank you for your feedback! 🎉');
        this.router.navigate(['/user/items']);
      },
      error: (err) => {
        console.error('Error submitting feedback:', err);
        alert('Failed to submit feedback. Please try again.');
        this.isSubmitting = false;
      },
    });
  }

  skipFeedback() {
    if (
      confirm('Are you sure you want to skip? You can provide feedback later.')
    ) {
      this.router.navigate(['/user/items']);
    }
  }
}
<div class="feedback-container">
  <!-- Success Message with Animation -->
  <div *ngIf="successMessage" class="success-toast" [@slideInOut]>
    <div class="toast-content">
      <span class="toast-icon">✅</span>
      <span class="toast-message">{{ successMessage }}</span>
      <button class="toast-close" (click)="successMessage = ''">✕</button>
    </div>
  </div>

  <!-- Main Feedback Card -->
  <div class="feedback-wrapper" [@fadeInUp]>
    <div class="feedback-card">
      <!-- Header Section -->
      <div class="card-header">
        <div class="header-icon">
          <svg
            width="40"
            height="40"
            viewBox="0 0 24 24"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M12 22C17.5228 22 22 17.5228 22 12C22 6.47715 17.5228 2 12 2C6.47715 2 2 6.47715 2 12C2 13.5997 2.37562 15.1116 3.04346 16.4525C3.22094 16.8088 3.28001 17.2161 3.17712 17.6006L2.58151 19.8267C2.32295 20.793 3.20701 21.677 4.17335 21.4185L6.39939 20.8229C6.78393 20.72 7.19121 20.7791 7.54753 20.9565C8.88837 21.6244 10.4003 22 12 22Z"
              stroke="currentColor"
              stroke-width="1.5"
              fill="none"
            />
            <path
              d="M8 8H16M8 12H13"
              stroke="currentColor"
              stroke-width="1.5"
              stroke-linecap="round"
            />
          </svg>
        </div>
        <div class="header-text">
          <h1>We Value Your Feedback</h1>
          <p>Your opinion helps us improve and serve you better</p>
        </div>
      </div>

      <!-- Form Section -->
      <form (ngSubmit)="onSubmit()" #form="ngForm" class="feedback-form">
        <!-- Name Input with Animation -->
        <div class="form-group" [@slideInLeft]>
          <label for="name" class="form-label">
            <span class="label-icon">👤</span>
            Full Name
          </label>
          <div class="input-wrapper">
            <input
              id="name"
              type="text"
              class="form-input"
              name="name"
              [(ngModel)]="feedback.customerName"
              #name="ngModel"
              required
              placeholder="Enter your full name"
            />
            <div class="input-border"></div>
          </div>
          <div *ngIf="name.invalid && name.touched" class="error-message">
            ⚠️ Name is required
          </div>
        </div>

        <!-- Email Input with Animation -->
        <div class="form-group" [@slideInLeft]>
          <label for="email" class="form-label">
            <span class="label-icon">📧</span>
            Email Address
          </label>
          <div class="input-wrapper">
            <input
              id="email"
              type="email"
              class="form-input"
              name="email"
              [(ngModel)]="feedback.email"
              #email="ngModel"
              required
              email
              placeholder="your@email.com"
            />
            <div class="input-border"></div>
          </div>
          <div *ngIf="email.invalid && email.touched" class="error-message">
            <span *ngIf="email.errors?.['required']">⚠️ Email is required</span>
            <span *ngIf="email.errors?.['email']"
              >⚠️ Please enter a valid email</span
            >
          </div>
        </div>

        <!-- Message Input with Animation -->
        <div class="form-group" [@slideInLeft]>
          <label for="message" class="form-label">
            <span class="label-icon">💬</span>
            Your Feedback
          </label>
          <div class="input-wrapper">
            <textarea
              id="message"
              class="form-textarea"
              name="message"
              rows="5"
              [(ngModel)]="feedback.message"
              #message="ngModel"
              required
              placeholder="Tell us about your experience..."
            ></textarea>
            <div class="input-border"></div>
          </div>
          <div class="char-counter" *ngIf="feedback.message?.length">
            {{ feedback.message.length }}/500 characters
          </div>
          <div *ngIf="message.invalid && message.touched" class="error-message">
            ⚠️ Feedback message is required
          </div>
        </div>

        <!-- Action Buttons -->
        <div class="form-actions" [@fadeInUp]>
          <button
            type="submit"
            class="btn-submit"
            [disabled]="form.invalid || isSubmitting"
          >
            <span class="btn-icon">✉️</span>
            <span>{{ isSubmitting ? "Sending..." : "Submit Feedback" }}</span>
          </button>
          <button type="button" class="btn-skip" (click)="skipFeedback()">
            <span class="btn-icon">⏭️</span>
            <span>Skip for Now</span>
          </button>
        </div>
      </form>

      <!-- Footer Note -->
      <div class="feedback-footer" [@fadeIn]>
        <div class="footer-note">
          <span class="note-icon">🌟</span>
          <span>Your feedback helps us improve our service</span>
        </div>
      </div>
    </div>
  </div>

  <!-- Loading Overlay -->
  <div class="loading-overlay" *ngIf="isSubmitting" [@fadeInOut]>
    <div class="loader-container">
      <div class="loader"></div>
      <p>Sending your feedback...</p>
    </div>
  </div>
</div>
